-- College Discovery Platform: 50 real colleges
-- IMPORTANT: numeric fees, cutoffs and placement figures are approximate seed values.
-- Verify against each institution/counselling authority before presenting as current facts.

CREATE TABLE IF NOT EXISTS colleges (
  id INTEGER PRIMARY KEY,
  college_name VARCHAR(255) NOT NULL,
  city VARCHAR(100) NOT NULL,
  state VARCHAR(100) NOT NULL,
  institution_type VARCHAR(100),
  courses TEXT,
  annual_fee_lakh_approx NUMERIC(6,2),
  cutoff_exam VARCHAR(150),
  cutoff_note TEXT,
  placement_rate_pct_approx NUMERIC(5,2),
  average_package_lpa_approx NUMERIC(7,2),
  highest_package_approx VARCHAR(50),
  rating_demo_out_of_5 NUMERIC(2,1),
  hostel VARCHAR(10),
  website TEXT,
  nirf_engineering_rank_2025 INTEGER,
  data_status TEXT,
  data_reference_year INTEGER
);

